import React, { useContext, useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "./AuthContext";

const GOOGLE_CLIENT_ID = process.env.REACT_APP_GOOGLE_CLIENT_ID;

export default function Login() {
  const { saveToken } = useContext(AuthContext);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [rememberMe, setRememberMe] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const [matrixColumns, setMatrixColumns] = useState([]);

  useEffect(() => {
    if (window.google && GOOGLE_CLIENT_ID) {
      window.google.accounts.id.initialize({
        client_id: GOOGLE_CLIENT_ID,
        callback: handleGoogleResponse,
      });

      window.google.accounts.id.renderButton(
        document.getElementById("googleSignInDiv"),
        {
          theme: "outline",
          size: "large",
          width: "400",
          text: "continue_with",
          shape: "rectangular",
        }
      );
    }
  }, []);

  const handleGoogleResponse = async (response) => {
    const googleToken = response.credential;
    setIsLoading(true);

    try {
      const res = await fetch("http://127.0.0.1:8000/auth/google", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id_token: googleToken }),
      });

      const data = await res.json();
      if (!res.ok) {
        alert("Google login failed");
        return;
      }

      saveToken(data.token, data.user);
      navigate("/join");
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogin = async () => {
    if (!email || !password) {
      alert("Please fill in all fields");
      return;
    }

    setIsLoading(true);
    try {
      const res = await fetch("http://127.0.0.1:8000/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });

      const data = await res.json();

      if (!res.ok) {
        alert(data.detail || "Invalid credentials");
        return;
      }

      saveToken(data.token, data.user);
      navigate("/join");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div style={{
      minHeight: "100vh",
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      background: "#1a1a2e",
      padding: "20px",
      fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
      position: "relative",
      overflow: "hidden"
    }}>
      {/* Animated Mesh Gradient Background */}
      <div style={{
        position: "absolute",
        top: "-50%",
        left: "-50%",
        width: "200%",
        height: "200%",
        background: `
          radial-gradient(circle at 20% 50%, rgba(120, 119, 198, 0.3), transparent 50%),
          radial-gradient(circle at 80% 80%, rgba(88, 166, 255, 0.3), transparent 50%),
          radial-gradient(circle at 40% 20%, rgba(255, 107, 107, 0.3), transparent 50%),
          radial-gradient(circle at 90% 10%, rgba(255, 195, 113, 0.3), transparent 50%),
          radial-gradient(circle at 10% 90%, rgba(72, 219, 251, 0.3), transparent 50%)
        `,
        animation: "meshMove 20s ease infinite",
        filter: "blur(60px)"
      }} />

      {/* Secondary animated layer */}
      <div style={{
        position: "absolute",
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        background: `
          radial-gradient(circle at 60% 70%, rgba(168, 85, 247, 0.2), transparent 40%),
          radial-gradient(circle at 30% 40%, rgba(59, 130, 246, 0.2), transparent 40%),
          radial-gradient(circle at 70% 30%, rgba(236, 72, 153, 0.2), transparent 40%)
        `,
        animation: "meshMove 15s ease infinite reverse",
        filter: "blur(80px)"
      }} />

      {/* Overlay gradient */}
      <div style={{
        position: "absolute",
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        background: "linear-gradient(180deg, rgba(26, 26, 46, 0.3) 0%, rgba(26, 26, 46, 0.8) 100%)"
      }} />

      {/* Floating orbs */}
      <div style={{
        position: "absolute",
        width: "300px",
        height: "300px",
        background: "radial-gradient(circle, rgba(120, 119, 198, 0.4), transparent 70%)",
        borderRadius: "50%",
        top: "10%",
        left: "10%",
        filter: "blur(60px)",
        animation: "float 25s infinite ease-in-out"
      }} />
      <div style={{
        position: "absolute",
        width: "400px",
        height: "400px",
        background: "radial-gradient(circle, rgba(88, 166, 255, 0.3), transparent 70%)",
        borderRadius: "50%",
        bottom: "5%",
        right: "5%",
        filter: "blur(70px)",
        animation: "float 20s infinite ease-in-out reverse"
      }} />

      <style>{`
        @keyframes meshMove {
          0%, 100% {
            transform: translate(0, 0) scale(1) rotate(0deg);
          }
          33% {
            transform: translate(5%, -5%) scale(1.1) rotate(120deg);
          }
          66% {
            transform: translate(-5%, 5%) scale(0.9) rotate(240deg);
          }
        }
        @keyframes float {
          0%, 100% {
            transform: translate(0, 0);
          }
          33% {
            transform: translate(30px, -30px);
          }
          66% {
            transform: translate(-30px, 30px);
          }
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes shimmer {
          0% { background-position: -1000px 0; }
          100% { background-position: 1000px 0; }
        }
        input:focus {
          outline: none;
          border-color: rgba(120, 119, 198, 0.8);
          box-shadow: 0 0 0 3px rgba(120, 119, 198, 0.2);
        }
        .hover-lift {
          transition: all 0.3s ease;
        }
        .hover-lift:hover {
          transform: translateY(-4px);
          box-shadow: 0 20px 60px rgba(120, 119, 198, 0.3);
        }
        button:disabled {
          opacity: 0.6;
          cursor: not-allowed;
        }
      `}</style>

      <div style={{
        width: "480px",
        background: "rgba(255, 255, 255, 0.95)",
        backdropFilter: "blur(20px) saturate(180%)",
        padding: "48px",
        borderRadius: "24px",
        boxShadow: "0 8px 32px rgba(31, 38, 135, 0.37)",
        border: "1px solid rgba(255, 255, 255, 0.18)",
        animation: "fadeIn 0.5s ease-out",
        position: "relative",
        zIndex: 10
      }}
      className="hover-lift">
        
        {/* Header */}
        <div style={{ textAlign: "center", marginBottom: "32px" }}>
          <h1 style={{
            fontSize: "32px",
            fontWeight: "700",
            background: "linear-gradient(135deg, #7877C6 0%, #58A6FF 100%)",
            WebkitBackgroundClip: "text",
            WebkitTextFillColor: "transparent",
            backgroundClip: "text",
            marginBottom: "8px"
          }}>
            Welcome back
          </h1>
          <p style={{
            color: "#64748b",
            fontSize: "15px"
          }}>
            Log in to your account
          </p>
        </div>

        {/* Email Field */}
        <div style={{ marginBottom: "20px" }}>
          <label style={{
            display: "block",
            fontWeight: "600",
            fontSize: "14px",
            color: "#1e293b",
            marginBottom: "8px"
          }}>
            Email address
          </label>
          <input
            type="email"
            placeholder="Enter your email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            onKeyPress={(e) => e.key === "Enter" && handleLogin()}
            style={{
              width: "100%",
              padding: "12px 16px",
              borderRadius: "12px",
              border: "2px solid #e2e8f0",
              fontSize: "15px",
              transition: "all 0.3s ease",
              backgroundColor: "#f8fafc",
              color: "#1e293b"
            }}
          />
        </div>

        {/* Password Field */}
        <div style={{ marginBottom: "16px" }}>
          <label style={{
            display: "block",
            fontWeight: "600",
            fontSize: "14px",
            color: "#1e293b",
            marginBottom: "8px"
          }}>
            Password
          </label>
          <input
            type="password"
            placeholder="Enter your password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            onKeyPress={(e) => e.key === "Enter" && handleLogin()}
            style={{
              width: "100%",
              padding: "12px 16px",
              borderRadius: "12px",
              border: "2px solid #e2e8f0",
              fontSize: "15px",
              transition: "all 0.3s ease",
              backgroundColor: "#f8fafc",
              color: "#1e293b"
            }}
          />
        </div>

        {/* Remember + Forgot */}
        <div style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "24px"
        }}>
          <label style={{
            display: "flex",
            alignItems: "center",
            cursor: "pointer",
            fontSize: "14px",
            color: "#64748b"
          }}>
            <input
              type="checkbox"
              checked={rememberMe}
              onChange={(e) => setRememberMe(e.target.checked)}
              style={{
                width: "16px",
                height: "16px",
                marginRight: "8px",
                cursor: "pointer",
                accentColor: "#7877C6"
              }}
            />
            Remember me
          </label>
          <a href="#" style={{
            color: "#7877C6",
            fontWeight: "500",
            fontSize: "14px",
            textDecoration: "none"
          }}>
            Forgot password?
          </a>
        </div>

        {/* Sign in button */}
        <button
          onClick={handleLogin}
          disabled={isLoading}
          style={{
            width: "100%",
            background: "linear-gradient(135deg, #7877C6 0%, #58A6FF 100%)",
            color: "#fff",
            padding: "14px",
            borderRadius: "12px",
            fontSize: "16px",
            fontWeight: "600",
            border: "none",
            cursor: "pointer",
            transition: "all 0.3s ease",
            boxShadow: "0 4px 15px rgba(120, 119, 198, 0.4)",
            position: "relative",
            overflow: "hidden"
          }}
          onMouseOver={(e) => {
            if (!isLoading) {
              e.target.style.transform = "translateY(-2px)";
              e.target.style.boxShadow = "0 6px 20px rgba(120, 119, 198, 0.6)";
            }
          }}
          onMouseOut={(e) => {
            e.target.style.transform = "translateY(0)";
            e.target.style.boxShadow = "0 4px 15px rgba(120, 119, 198, 0.4)";
          }}
        >
          {isLoading ? "Signing in..." : "Log in"}
        </button>

        {/* Divider */}
        <div style={{
          textAlign: "center",
          margin: "24px 0",
          color: "#94a3b8",
          fontSize: "14px",
          position: "relative"
        }}>
          <div style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: "50%",
            height: "1px",
            background: "linear-gradient(90deg, transparent, #e2e8f0, transparent)"
          }} />
          <span style={{
            position: "relative",
            background: "rgba(255, 255, 255, 0.95)",
            padding: "0 16px"
          }}>
            — Or continue with —
          </span>
        </div>

        {/* Google Sign-In Button */}
        <div
          id="googleSignInDiv"
          style={{
            display: "flex",
            justifyContent: "center",
            marginBottom: "16px"
          }}
        ></div>

        {/* Signup link */}
        <div style={{
          textAlign: "center",
          marginTop: "24px",
          fontSize: "14px",
          color: "#64748b"
        }}>
          Don't have an account?{" "}
          <a
            href="/signup"
            style={{
              color: "#7877C6",
              fontWeight: "600",
              textDecoration: "none"
            }}
          >
            Sign up here
          </a>
        </div>

        {/* Load Google script */}
        <script src="https://accounts.google.com/gsi/client" async defer></script>
      </div>
    </div>
  );
}
